"""Versioned website analytics disclosure; English text is explicitly marked on all editions."""
import re
CONTROLS = '''<button type="button" class="cookie-preferences-link" data-cookie-open>Cookie preferences</button><details class="analytics-choice" lang="en" dir="ltr"><summary>Website analytics · <span data-analytics-state>Basic</span></summary><p>Basic visitor counts use Vercel. With your permission, PostHog measures visits, approximate location, clicks and time on pages, and records masked website interactions for replay and heatmaps. No app accounts or call content. You can stop all website analytics here.</p><div><a href="/privacy.html?lang=en#website-analytics" lang="en">Analytics privacy (English)</a> · <button type="button" data-analytics-allow>Allow detailed analytics</button><button type="button" data-analytics-deny>Turn all analytics off</button></div></details>'''
BANNER = '''<aside id="website-analytics-banner" class="website-analytics-banner ph-no-capture" lang="en" dir="ltr" role="dialog" aria-modal="false" aria-labelledby="cookie-notice-title" hidden><strong id="cookie-notice-title">We use cookies</strong><p>We use cookies and similar technologies to analyze website traffic and support our advertising.</p><div class="cookie-actions"><button type="button" data-cookie-accept>Allow cookies</button><button type="button" data-cookie-reject>Reject optional</button><a href="#cookie-preferences" data-cookie-manage aria-controls="cookie-preferences" aria-expanded="false">Cookie settings</a></div><div id="cookie-preferences" data-cookie-settings hidden><label><input type="checkbox" data-cookie-analytics/> <b>Analytics</b></label><p>PostHog measures visits, clicks and time on pages, with heatmaps and masked session replay. Forms and call content are excluded. Cookie-free Vercel counts run by default. Turning Analytics off stops both.</p><label><input type="checkbox" data-cookie-ads/> <b>Advertising cookies</b></label><p>Allow Meta to measure ads and show Dial Santa ads to website visitors.</p><p>Essential storage remembers your language and privacy choices. Change your choices anytime using Cookie preferences in the footer.</p><button type="button" data-cookie-save>Save preferences</button></div><p data-cookie-signal hidden>Your browser privacy signal keeps optional tracking off.</p><p class="cookie-note"><a href="/privacy.html?lang=en#website-analytics">Cookie policy (English)</a></p></aside>'''
ADS_CONTROLS = '''<details class="analytics-choice ads-choice" lang="en" dir="ltr"><summary>Advertising measurement · <span data-ads-state data-off="Off" data-on="On">Off</span></summary><p>Meta advertising cookies stay off until you allow them. They measure our ads and help show Dial Santa ads to website visitors. No child profiles, app accounts, form entries or call content. Browser privacy signals take priority. <a href="/privacy.html?lang=en#website-ads">Privacy details (English)</a></p><div><button type="button" data-ads-allow>Allow</button><button type="button" data-ads-deny>Turn off</button></div></details>'''
ADS_POLICY = '''<section lang="en" dir="ltr" data-website-ads-policy="20261013"><h2 id="website-ads">Website advertising cookies — updated October 13, 2026 (English)</h2><p>With your permission, this website uses the Meta Pixel to measure whether our Facebook and Instagram ads bring parents to dialsanta.app and show Dial Santa ads to people who have visited. Meta receives pages viewed, App Store button taps, browser and device information, your IP address and Meta cookies (such as _fbp and _fbc) that can last up to 90 days; Meta may link this with your Meta account under its privacy policy. We do not send names, email addresses, child profiles, app accounts, form entries or call content. Automatic advanced matching, automatic event collection and automatic configuration are off; Limited Data Use is on where it applies.</p><p>Advertising cookies stay off everywhere until you choose Allow cookies or enable Advertising cookies and save your preferences. Existing explicit permission remains valid. Reject optional turns off advertising and website analytics. Reopen Cookie preferences in the footer to change your choice; the separate Advertising measurement control also works. Global Privacy Control and Do Not Track take priority. Turning advertising off stops future sharing and clears the website's _fbp and _fbc cookies, but cannot delete cookies on Meta's domains or data already received by Meta. The Pixel does not run on checkout or confirmation pages or inside the app. Essential browser storage remembers your language and privacy choices.</p></section>'''
POLICY = '''<section lang="en" dir="ltr" data-website-analytics-policy="20261013"><h2 id="website-analytics">Website analytics — updated October 13, 2026 (English)</h2>
<p>This section replaces the earlier website-analytics description. It applies to public marketing pages in every website language. App analytics and advertising measurement have separate controls below.</p>
<h3 id="vercel-analytics">Basic visitor measurement: Vercel</h3>
<p>Basic Vercel Web Analytics starts automatically on eligible public pages. It measures page views, approximate visitors, referring sites, country/region/city estimates, browser and device information, and App Store button clicks. Vercel derives a visitor hash from network information and discards it within 24 hours; it is not a permanent identity. We remove URL queries and fragments from events. This measurement sets no cookies and does not record website sessions. Selecting Reject optional, saving Analytics off in Cookie preferences, or selecting Turn all analytics off, or sending Global Privacy Control or Do Not Track, stops future website analytics. Counts are estimates and may exclude blocked visits.</p>
<h3>Detailed website analytics: PostHog</h3>
<p>PostHog (US hosting) starts only after you select Allow cookies, save Analytics on in Cookie preferences, or select Allow detailed analytics. It measures page views and exits, referring domains, device/browser/operating-system information, approximate location derived from network information, navigation and App Store clicks, scroll depth, active time, video engagement, and performance. A random browser identifier and session identifier connect activity across pages and repeat visits using browser local storage. They are not linked to your Dial Santa app account. The PostHog project is configured to discard raw IP addresses.</p>
<p>Detailed analytics also includes click and scroll heatmaps and masked session replay of the public website. Replay reconstructs page layout and interactions; it does not record your camera, microphone or calls. Inputs and editable or designated sensitive text are masked; public marketing copy remains visible. Forms, editable areas, embedded frames, canvas, video/audio content and designated sensitive elements are blocked. Network request bodies, headers and console logs are not recorded. New replays are retained for 30 days. Checkout, confirmation and private routes are excluded. We strip query strings and fragments and do not send names, email addresses, child profiles, form entries or call content.</p>
<p>Earlier permission for basic counts does not authorize detailed analytics or replay: we ask again. You can change your choice using Cookie preferences in the website footer. Turning analytics off stops future collection and clears PostHog's local tracking persistence; it does not erase data already received. Browser privacy signals take priority. Anonymous website measurements are separate from app analytics, purchases and advertising. For questions or deletion requests, contact <a href="mailto:hohoho@dialsanta.app">hohoho@dialsanta.app</a>. <a href="https://vercel.com/docs/analytics/privacy-policy">Vercel privacy details</a> · <a href="https://posthog.com/docs/privacy">PostHog privacy details</a>.</p></section>'''
def apply_analytics_markup(html, public=True):
    html = re.sub(r'<button\b[^>]*\bdata-cookie-open[^>]*>.*?</button>', '', html, flags=re.S)
    html = re.sub(r'<details\b[^>]*class="analytics-choice"[^>]*>.*?</details>', lambda m:CONTROLS, html, flags=re.S)
    html = re.sub(r'<aside\b[^>]*id="website-analytics-banner".*?</aside>\n?', '', html, flags=re.S)
    html = re.sub(r'<div\b[^>]*\bdata-ads-banner[^>]*>.*?</div></div>', '', html, flags=re.S)
    html = re.sub(r'<details\b[^>]*class="analytics-choice ads-choice"[^>]*>.*?</details>', lambda m:ADS_CONTROLS, html, flags=re.S)
    html = re.sub(r'<script\b[^>]*src="/cookie-consent\.js[^"]*"[^>]*></script>\n?', '', html)
    if public and 'data-analytics-state' in html:
        html = html.replace('</body>', BANNER+'\n<script defer src="/cookie-consent.js?v=20261013-cookies-link"></script>\n</body>')
    if 'data-analytics-state' in html and '/analytics.css' not in html:
        html = html.replace('</head>','<link rel="stylesheet" href="/analytics.css?v=20261013"/>\n</head>')
    html = re.sub(r'/acquisition\.js(?:\?v=[^"\s]+)?', '/acquisition.js?v=20261013-cookies', html)
    html = re.sub(r'/(meta-pixel\.js|analytics\.css)(?:\?v=[^"\s]+)?', r'/\1?v=20261013-cookies', html)
    html = re.sub(r'/analytics\.css(?:\?v=[^"\s]+)?', '/analytics.css?v=20261013-cookies-link', html)
    if 'id="website-ads"' in html:
        html = re.sub(r'<section lang="en" dir="ltr" data-website-ads-policy="20261013">.*?</section>', lambda m:ADS_POLICY, html, flags=re.S)
        if 'data-website-ads-policy' not in html:
            html = re.sub(r'<h2\b[^>]*id="website-ads"[^>]*>.*?(?=<h2\b)', lambda m:ADS_POLICY+'\n', html, flags=re.S)
    if 'id="website-analytics"' in html:
        html = re.sub(r'<div class="date"[^>]*>.*?</div>', '<div class="date" lang="en" dir="ltr">Effective October 13, 2026 (English analytics update)</div>', html, flags=re.S)
        html = re.sub(r'<section lang="en" dir="ltr" data-website-analytics-policy="20261013">.*?</section>', lambda m:POLICY, html, flags=re.S)
        if 'data-website-analytics-policy' not in html:
            html = re.sub(r'<h2\b[^>]*id="website-analytics"[^>]*>.*?(?=<h2\b[^>]*id="app-analytics")',lambda m:POLICY+'\n',html,flags=re.S)
    return html
